def solve(n, edges, s, t):
    import heapq

    if s == t:
        return 0

    # Initialize distance to infinity
    dist = [float('inf')] * n
    dist[s] = 0

    # Priority queue: (distance, node)
    pq = [(0, s)]

    while pq:
        current_dist, u = heapq.heappop(pq)

        # Skip if we have a shorter distance already recorded
        if current_dist > dist[u]:
            continue

        for edge in edges:
            if edge[0] == u:
                v, w = edge[1], edge[2]
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    heapq.heappush(pq, (dist[v], v))

    return dist[t] if dist[t] != float('inf') else -1
